={{ JSON.stringify({
  model: 'claude-sonnet-5-5',
  max_tokens: 3000,
  output_config: { effort: 'medium', format: { type: 'json_schema', schema: {"type":"object","properties":{"brand_fit":{"type":"integer"},"rationale":{"type":"string"},"risk_flags":{"type":"array","items":{"type":"string"}},"competitor_mentions":{"type":"array","items":{"type":"string"}},"confidence":{"type":"string","enum":["low","medium","high"]}},"required":["brand_fit","rationale","risk_flags","competitor_mentions","confidence"],"additionalProperties":false} } },
  system: "You judge creator-brand fit for a Thai creator agency. Use only the brief and the creator data provided. brand_fit is 0-100. Cite post dates or permalinks in the rationale (max 40 words). Flag brand-safety and competitor issues; never hide them. Never invent numbers. Thai and English captions are both normal.",
  messages: [{ role: 'user', content: 'BRIEF: ' + JSON.stringify($('Validate criteria').first().json) + '\nCREATOR: ' + JSON.stringify({ handle: $json.handle, platform: $json.platform, tier: $json.tier, recent_captions: $json.recent_captions, content_tags: $json.content_tags, past_brands: $json.past_brands, sentiment: $json.comment_sentiment }) }]
}) }}

